import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * A filter applied by {@link CustomerRepository} when listing or counting
 * customers.
 *
 * @param name      free text; split on whitespace into terms that must all
 *                  match, ignoring case and accents; blank means "match
 *                  everyone"
 * @param statuses  statuses to restrict to; empty means "match every status"
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether {@code customer} satisfies both the name and the status filter. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    private List<String> nameTerms() {
        return Arrays.stream(name.trim().split("\\s+"))
                .filter(term -> !term.isEmpty())
                .map(CustomerFilter::normalize)
                .toList();
    }

    private static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
    }
}
